for (const page of pages) { const out=join('dist',page.path); await mkdir(dirname(out),{recursive:true}); await writeFile(out,shell(page)); }
const urls=pages.filter(p=>!p.noindex&&p.path!=='404.html').map(p=>`${domain}/${p.path==='index.html'?'':p.path.replace(/index\.html$/,'')}`);
await writeFile('dist/sitemap.xml',`<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">${urls.map(u=>`<url><loc>${u}</loc></url>`).join('')}</urlset>`);
